export const topics={
 cyber:{label:'cybersecurity',words:['cyber','security','beveilig','hacken','hacking','veiligheid','netwerk']},
 ondernemen:{label:'ondernemen',words:['ondernem','bedrijf starten','eigen bedrijf','startup','start-up','businessplan']},
 creatief:{label:'creatief ontwerpen',words:['creatief','creatieve','ontwerp','design','kunst','creativiteit']},
 zorg:{label:'zorg en herstel',words:['zorg','herstel','psychisch','psychologie','welzijn','hersenletsel','mensen helpen']},
 duurzaam:{label:'duurzaamheid',words:['duurzaam','klimaat','milieu','circulair','biodiversiteit','natuur']},
 data:{label:'data-analyse',words:['data','analytics','analyse','analyseren','business intelligence',' ai ','kunstmatige intelligentie']}
};
export function detect(text){const s=' '+text.toLowerCase().replace(/\b(geen|niet|zonder)\s+.*?(?=[,.;!?]|\smaar\s|\swel\s|$)/g,' ')+' ';return Object.keys(topics).filter(k=>topics[k].words.some(w=>s.includes(w)));}
export function rank(data,profile){const wanted=profile.topics||[];return data.map(m=>({...m,matched:m.tags.filter(t=>wanted.includes(t))})).filter(m=>m.matched.length).sort((a,b)=>b.matched.length-a.matched.length||a.title.localeCompare(b.title,'nl')).slice(0,3);}
export function createSession(){return {step:'study',study:'',topics:[],direction:'',focus:'',turns:0};}
export const firstQuestion='Welke opleiding volg je? Noem alleen je studierichting; je naam of studentnummer is niet nodig.';
export function respond(s,input,data){const t=input.trim().slice(0,500), low=t.toLowerCase();s.turns++;
 if(/^(opnieuw|reset|begin opnieuw)[.! ]*$/.test(low)){Object.assign(s,createSession());return {text:firstQuestion};}
 if(/studieadviseur|mens spreken|persoon spreken/.test(low))return {text:'Bespreek je wensen met de studieadviseur van je eigen opleiding. Die kan toelating, planning en goedkeuring met je controleren. Ik kan je niet rechtstreeks doorverbinden.',handoff:true};
 if(!t||/^(weet ik niet|geen idee|ik weet het niet|weet niet)[.! ]*$/.test(low)){if(s.step==='study')return {text:'Je mag je opleiding overslaan. Zeg bijvoorbeeld “overslaan”. Wat je wilt leren is het belangrijkste.'};if(s.turns>5)return {text:'Ik heb nog te weinig informatie voor een passende aanbeveling. Een studieadviseur kan samen met jou je interesses verkennen. Je kunt ook een onderwerp noemen dat je leuk vindt.',handoff:true};return {text:'Wat doe je graag: iets ontwerpen, mensen helpen, een bedrijf opzetten, digitale veiligheid onderzoeken, data analyseren of met duurzaamheid werken? Je mag ook iets anders noemen.'};}
 if(s.step==='study'){s.study=low==='overslaan'?'Niet opgegeven':t;s.step='interests';return {text:'Wat zou je graag willen leren of doen tijdens je minor? Je mag ook iets noemen buiten je huidige opleiding.'};}
 if(s.step==='interests'){s.topics=detect(t);if(!s.topics.length)return {text:'Ik herken nog geen onderwerp in mijn beperkte verzameling. Kun je concreet vertellen wat je wilt leren? Vind ik geen passende minor, bespreek je wens dan met je studieadviseur.',handoff:true};s.step='direction';return {text:'Je noemt '+s.topics.map(k=>topics[k].label).join(' en ')+'. Wil je je huidige vakgebied verdiepen, een andere richting verkennen, of allebei?'};}
 if(s.step==='direction'){if(!/verdiep|verbred|verken|ander|allebei|beide/.test(low))return {text:'Bedoel je verdiepen in je vakgebied, verbreden naar een andere richting, of allebei?'};s.direction=/allebei|beide/.test(low)?'Allebei':/verdiep/.test(low)?'Verdiepen':'Verbreden';s.step='focus';const q={cyber:'Wil je vooral leren hoe je organisaties beschermt, of de technische kant van beveiliging onderzoeken?',ondernemen:'Wil je een eigen bedrijf starten, of eerst ontdekken of ondernemen bij je past?',creatief:'Wil je vooral nieuwe ideeën leren bedenken of concrete ontwerpen maken?',zorg:'Wil je vooral mensen ondersteunen bij herstel of meer leren over psychische problemen?',duurzaam:'Wil je vooral de natuur en het klimaat begrijpen of organisaties helpen duurzamer te werken?',data:'Wil je data leren analyseren of leren hoe organisaties er betere beslissingen mee nemen?'};return {text:q[s.topics[0]]};}
 if(s.step==='focus'){s.focus=t;const extra=detect(t);s.topics=[...new Set([...s.topics,...extra])];s.step='results';return results(s,data);}
 if(s.step==='results'){if(/waarom|uitleg|toelicht/.test(low))return results(s,data);if(/toelat|deadline|startdatum|inschrij|locatie|reistijd|studiepunten|\bec\b/.test(low))return {text:'Ik kan actuele toelating, locatie, studiepunten en inschrijfdata niet betrouwbaar bevestigen met deze beperkte gegevens. Open de bron bij de minor en controleer dit met je studieadviseur.',handoff:true};const next=detect(t);if(next.length){s.topics=next;s.step='direction';return {text:'Ik pas je interesse aan naar '+next.map(k=>topics[k].label).join(' en ')+'. Wil je verdiepen, verbreden of allebei?'};}return {text:'Wil je een ander onderwerp verkennen? Noem je nieuwe interesse, zeg “waarom” voor uitleg of “opnieuw” om te beginnen. Bij vragen buiten deze gegevens helpt je studieadviseur verder.'};}
}
function results(s,data){const found=rank(data,s);if(!found.length)return {text:'Ik vind geen onderbouwde match in deze beperkte verzameling. Dat betekent niet dat er geen geschikte minor bestaat. Vraag je studieadviseur om mee te zoeken.',results:[],handoff:true};return {text:'Ik heb '+found.length+' mogelijke '+(found.length===1?'match':'matches')+' gevonden op basis van je genoemde interesses. '+found.map(m=>m.title+': '+m.summary).join(' ')+' Dit is een inhoudelijke verkenning, geen bevestiging van toelating of beschikbaarheid. Bekijk de bron en bespreek je keuze met je studieadviseur.',results:found};}
